-- 기존 academy_shared_data 테이블에 한 건의 JSON 데이터를 저장합니다.
INSERT INTO public.academy_shared_data(key,value) VALUES ('original.cells.사용방법.0000','[{"c":"C3","v":"관생 관리 엑셀 (v1.8.12)"},{"c":"F3","v":"업데이트 확인하기!"},{"c":"AA3","v":"초안본 최초 완성(이름정의, 설정 시트 제작) (v1.0.0)"},{"c":"C4","v":"본 시트는 이 엑셀을 실제로 사용하시는 분들을 위한 사용설명서입니다."},{"c":"AA4","v":"입관원서 시트 추가 (v1.1.0)"},{"c":"AA5","v":"출석부 제작 및 입관원서와 동기화 (v1.2.0)"},{"c":"C6","v":"목차(챕터를 눌러 각 챕터별 사용설명서로 바로가기)"},{"c":"AA6","v":"현황판 1차 제작 (v1.3.1)"},{"c":"C7","v":"1. 설정시트는 무엇이고, 어떻게 사용하나요?"},{"c":"AA7","v":"현황판 2차 업데이트 (v1.3.2)"},{"c":"C8","v":"2. 입관원서를 작성하는 방법은 어떻게 되나요?"},{"c":"AA8","v":"현황판 3차 업데이트 (v1.3.3)"},{"c":"C9","v":"3. 출석부는 어떻게 사용하나요?"},{"c":"AA9","v":"각 시트별 수정 가능 범위 및 시트 잠금 (v1.4.0)"},{"c":"C10","v":"4. 등하원 차량 장소 및 시간은 어떻게 사용하나요?"},{"c":"AA10","v":"교육비 현황(상, 하반기) 시트 제작 (v1.5.0)"},{"c":"C11","v":"5. 현황판은 어떻게 사용하나요?"},{"c":"AA11","v":"등하원 스케줄 전용 시트 제작, 입관원서 등원 관련 내용 삭제, 입관원서 내용 변경에 따른 의존성 있는 시트 전반적인 수정 (v1.6.0)"},{"c":"C12","v":"6. 교육비 현황은 어떻게 사용하나요?"},{"c":"AA12","v":"스크립트 자동화 추가 (v1.7.0)"},{"c":"AA13","v":"스크립트가 온라인 환경에서 작동 안함 확인 -> 버튼 제거 및 스크립트 제거(v1.8.0)"},{"c":"C14","v":"7. 기타 문의는 제작자 이메일(ehgis2344@gmail.com) 혹은 \n전화번호(010-8871-3855)로 문의 부탁드립니다."},{"c":"AA14","v":"등하원 스케줄 관리 시트에 동적 배열 함수 추가, 이를 기반으로 등하원_월수금 및 화목에 자동 업데이트 되도록 수정(v1.8.1)"},{"c":"AA15","v":"사용 설명서 업데이트(v1.8.2)"},{"c":"AA16","v":"출석부 기능 업데이트(실제 출석하는 요일 및 시간에만 하얀색 칸으로 변경), 등하원 시간대 별로 나누어 출력하도록 변경(v1.8.3)"},{"c":"AA17","v":"교육비 이름순 나열, 현황판 테두리 추가, 등하원 시간대 분리, 기타 출력시 가독성을 높이기 위한 업데이트 (v1.8.4)"},{"c":"AA18","v":"출력시 작은 사이즈로 나오는 것을 보완. 출석부에도 교차수업 여부 표시, 현황판에 기타로 설정시 교차수업 반영 안되던것 수정, 기타 가독성 업데이트 (v1.8.5)"},{"c":"AA19","v":"실제 출력시 가독성을 높이기 위한 출석부 업데이트 (v1.8.6)"},{"c":"AA20","v":"등하원 행 5개 삭제 및 가독성 향상, 출석부 주 1회 조건부 서식 추가 및 가독성 향상, 업데이트에 따른 사용 설명서 수정 (v1.8.7)"},{"c":"AA21","v":"현황판에 원명, 서원 구분 및 2시 현황판 상단 시간표 표시 기능 추가, 사용 설명서 내용 수정 (v 1.8.8)"},{"c":"AA22","v":"현황판 요일 정렬 기준 수정 (v 1.8.9)"},{"c":"AA23","v":"등하원 월수금, 화목 정렬 방식 수정, 현황판 정렬 방식 수정(부분적), 교육비 현황 예금주 삭제, 가독성 제고 (v 1.8.10)"},{"c":"AA24","v":"교육비 현황 페이지 추가, 전체적인 비율 수정, 현황판에 최대 성 이 름 AA까지 들어가도록 수정 (v 1.8.11)"},{"c":"AA25","v":"등하원 스케줄 관리 시트에서 Y, N 값 필터링 후 출력 (v 1.8.12)"},{"c":"C100","v":"1-1. 설정시트 안내"},{"c":"C102","v":"설정 시트는 출석부 사용에 필요한 여러 기준값(기준월, 요일패턴, 시간대 등)을 모아둔 공간입니다.\n이 값들은 이름정의(Name Manager) 로 관리되며, 사용자가 잘못 입력하거나 형식을 틀리게 입력하는 것을 방지해줍니다."},{"c":"C106","v":"1-2. 왜 이름정의를 사용하나요?"},{"c":"C108","v":"\t•\t  사용자가 잘못된 데이터를 입력하는 것을 미리 막아줍니다.\n\t•\t  여러 시트에서 동일한 기준을 불러다 쓸 수 있어, 데이터를 한 곳에서만 관리하면 됩니다.\n\t•\t  기준월, 요일, 시간대 같은 반복 항목을 편리하게 선택할 수 있습니다."},{"c":"C113","v":"1-3. 각종 데이터 추가 방법(기준월을 기준으로 설명)"},{"c":"C115","v":"시간이 지나면 기준월도 함께 늘려주어야 합니다.\n예를 들어, 현재가 2028년 1월인데 설정 시트에는 2027년 12월까지만 입력돼 있다면,\n그 아래에 2028.01.01 을 새로 추가해 주세요.\n\n⚠️ 주의:\n\t•\t  항상 마지막 행에만 추가하세요.\n\t•\t  중간에 빈 행을 만들면 동작이 깨질 수 있습니다.\n\t•\t  입력 형식(YYYY.MM.DD) 을 반드시 지켜주세요."},{"c":"C125","v":"1-4. 다른 항목들도 마찬가지입니다."},{"c":"C127","v":"\t•\t  요일패턴 : “월수금”, “화목”, “기타” 외에는 입력할 수 없습니다.\n\t•  \t시간대 : 14:00 ~ 21:00 사이 정해진 값만 사용합니다.\n\t•  \t이런 값들은 설정 시트에서 미리 정의돼 있으므로, 사용자는 선택만 하면 됩니다."},{"c":"C132","v":"1-5. 요약하자면?"},{"c":"C134","v":"설정 시트는 출석부가 제대로 작동하기 위한 기준값 창고입니다.\n사용자는 정해진 형식대로 새로운 값을 마지막에 추가하는 것만 기억하면 됩니다."},{"c":"L136","v":"목차로"},{"c":"C200","v":"2-1. 입관원서 시트 안내"},{"c":"C202","v":"입관원서 시트는 원생의 기본 정보를 최초로 입력하고 관리하는 공간입니다.\n이 시트는 출석부를 비롯한 다른 모든 기능의 기초 데이터가 되므로, 원생의 데이터를 입력하는 부분을 \n제외한 모든 셀은 수정되지 않습니다."},{"c":"C207","v":"2-2. 왜 시트를 잠궈두나요?"},{"c":"C209","v":"\t•\t  잘못된 수정이나 삭제로 인해 출석부와 연결된 데이터가 깨지는 것을 방지합니다.\n\t•\t  실수로 수식을 지우거나, 형식을 바꾸는 일이 없도록 하기 위함입니다.\n\t•\t  따라서 일반 사용자는 함수로 구현된 일부 셀을 직접 수정할 수 없고, 필요한 경우 관리자에게 요청해야 합니다."},{"c":"C214","v":"2-3. 수정이 가능한 부분"},{"c":"C216","v":"•\t  원생의 정보를 입력하는 시트는 잠금이 해제되어 있으니 언제든 수정/삭제가 가능합니다."},{"c":"C219","v":"2-4. 요약하자면?"},{"c":"C221","v":"입관원서 시트는 출석부의 뿌리 데이터입니다.\n실수 방지를 위해 특정 셀은 잠가 두었으며, 사용자는 직접 고칠 필요가 없습니다.\n원생의 정보를 입력하는 부분은 잠가두지 않았으며, 언제든 수정/삭제가 가능합니다."},{"c":"L224","v":"목차로"},{"c":"C300","v":"3-1. 출석부(월수목, 화목 모두) 시트 안내"},{"c":"C302","v":"본 출석부는 입관원서에 입력된 내용을 바탕으로 원생들을 자동으로 월수금, 화목에 실제 출석 시간대에 맞추어 \n분류해주는 기능을 합니다. 따라서 일부 셀을 제외하고 모두 수정이 불가능하게 잠금처리 되어있습니다."},{"c":"C306","v":"3-2. 왜 시트를 잠궈두나요?"},{"c":"C308","v":"설명서 2-2를 참고해주시기 바랍니다."},{"c":"C311","v":"3-3. 어떻게 사용하나요?"},{"c":"C313","v":"입관원서에 작성된 내용을 기반으로 이미 원생들에 정보가 출석부로 자동 배치됩니다.\n또한 출석부 최상단에 년, 월을 선택하면 해당 달력을 기반으로 출석부가 업데이트 됩니다.\n\n또한 해당 출석부는 원생이 나오는 날짜에 따라 노란색, 주말은 빨간색으로 셀이 채워집니다. 여기서부터는 \n조금 복잡할 수 있으니 자세히 읽어주시기 바랍니다. 예시를 들어 설명하겠습니다.\n\n예를 들어, 한 원생이 월요일 3시, 화요일 5시, 금요일 6시 수업에 나온다고 가정하겠습니다.\n이 경우 출석부에서는 해당 원생이 실제 출석하는 요일 및 시간에만 빈칸이 뚫립니다.\n\n따라서 출석부를 실제로 사용하실 때에는,\n\t•\t 월수금 반, 화목 반, 그리고 각 시간대별 명단을 반드시 확인하시어 중복 반영이나 누락 없이 출석 체크를 \n  진행해 주시기 바랍니다."},{"c":"C328","v":"3-4. 요약하자면?"},{"c":"C330","v":"출석부는 입관원서 데이터를 기반으로 자동으로 작성됩니다.\n실제 원생이 출석하는 시간 및 요일에만 빈칸이 생기므로 사용자는 별도의 조작이 필요 없습니다.\n월수금, 화목 반과 각 시간대 명단을 반드시 확인해서 체크해주시기 바랍니다."},{"c":"L333","v":"목차로"},{"c":"C400","v":"4-1. 등하원 스케줄 관리 시트 안내"},{"c":"C402","v":"모든 원생들의 등하원 스케줄을 입력하는 시트입니다. 여기에 데이터를 입력하거나 수정하면, \n등하원_월수금, 등하원_화목 시트에 내용이 자동으로 반영됩니다."},{"c":"C406","v":"4-2. 등하원 월수금, 등하원 화목 시트 안내"},{"c":"C408","v":"자동으로 생성되는 등하원 정보 정리본입니다. 이 시트들의 내용은 수식에 의해 자동으로 채워지므로, \n사용자가 직접 데이터를 입력하거나 수정해서는 안됩니다. 따라서 해당 시트는 모든 영역이 수정 불가능 합니다."},{"c":"C412","v":"4-3. 등하원 스케줄 관리 시트 입력 방법"},{"c":"C414","v":"모든 작업은 이 시트에서만 진행하면 됩니다. 아래 규칙에 따라 스케줄을 입력해 주세요.\n학생 정보 입력:\n - 학생 정보는 자동으로 입관원서에서 불러와집니다. 따라서 사용자가 직접 추가하거나 수정할 일은 없으므로 \n  해당 셀은 잠겨있습니다.\n\n시간 및 장소 입력:\n - F, G열에는 등원 시간과 장소를 입력합니다.\n - H, I열에는 하원 시간과 장소를 입력합니다."},{"c":"C425","v":"4-4. 요약하자면?"},{"c":"C427","v":"사용자는 등하원 스케줄 관리 시트에 스케줄만 정확히 입력하면 됩니다. 그럼 등하원_월수금, 등하원_화목 시트에 \n자동으로 반영되어 원하는 최종 정리본을 즉시 확인할 수 있습니다."},{"c":"C431","v":"4-5. 입력시 주의사항"},{"c":"C433","v":"1. 등하원 월수금, 화목 시트에 아무런 값이 나오지 않아요.\n  A : 등하원 스케줄 관리 시트에 시간과 장소가 모두 입력되었는지 확인해주세요. 하나라도 비어있으면 \n       해당 스케줄은 집계되지 않습니다.\n\n2. 연락처가 표시되지 않아요.\n  A : 입관원서 시트에 해당 학생의 고유번호와 연락처가 올바르게 입력되어 있는지 확인해 주세요. 고유번호가 일치해야 \n      연락처를 가져올 수 있습니다."},{"c":"L440","v":"목차로"},{"c":"C500","v":"5-1. 현황판 시트 안내"},{"c":"C502","v":"현황판 시트는 입관원서에 작성된 내용을 바탕으로 자동으로 출석 요일, 시간대에 원생이 배치되는 기능을 수행합니다.\n본 시트는 거의 대부분 함수로 이루어져 있으므로 일부 셀을 제외하고 모두 수정이 불가능하게 잠금처리 되어있습니다."},{"c":"C506","v":"5-2. 왜 시트를 잠궈두나요?"},{"c":"C508","v":"설명서 2-2를 참고해주시기 바랍니다."},{"c":"C511","v":"5-3 어떻게 사용하나요?"},{"c":"C513","v":"현황판은 별다른 구체적인 사용 방법이 없습니다.\n해당 시트에서 수정 가능한 부분은 각 요일 및 시간대에 존재하는 굵은 박스 내부입니다.\n해당 부분은 비고란으로 별도로 관리가 필요한 원생을 작성해주시면 됩니다.\n또한 2시에 있는 원명, 서원은 직접 수정이 가능합니다."},{"c":"C519","v":"5-4. 요약하자면?"},{"c":"C521","v":"해당 시트는 모든 기능이 자동화 되어있으므로 조금만 수정하면 오류가 발생할 수 있어 대부분 수정이 불가합니다.\n유일하게 수정이 가능한 부분은 굵은 박스 내부로, 별도 관리가 필요한 원생이 있다면 작성해주세요."},{"c":"L523","v":"목차로"},{"c":"C600","v":"6-1. 교육비 현황 시트 안내"},{"c":"C602","v":"교육비 현황 시트는 입관원서에 작성된 내용을 바탕으로 자동으로 원생 전부를 불러옵니다. 계좌이체의 경우 예금주 칸에 \n별도로 뜨도록 하였습니다. 본 시트는 정보를 불러오는 부분이 함수로 이루어져 있으므로 해당 셀은 수정이 불가능하도록 \n잠금처리 되어있습니다."},{"c":"C607","v":"6-2. 왜 시트를 잠궈두나요?"},{"c":"C609","v":"설명서 2-2를 참고해주시기 바랍니다."},{"c":"C612","v":"6-3. 어떻게 사용하나요?"},{"c":"C614","v":"교육비 현황은 사실 별도의 사용 설명서가 필요 없을 정도로 직관적으로 되어있습니다. \n비고엔 원하시는 내용을 각 월엔 납부 여부 등 원하시는 내용을 기입하시면 됩니다."},{"c":"C618","v":"6-4. 요약하자면?"},{"c":"C620","v":"정보를 불러오는 것은 함수로 구현되어있습니다.\n원하시는 대로 나머지 부분은 수정하셔도 됩니다. 입력 형식도 제한이 없습니다."},{"c":"L622","v":"목차로"}]'::jsonb) ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, updated_at=now();
